from pathlib import Path

scenario = Path("scenarios/missions/d66_lvl10-16_mission_01_blacksun.md")
s = scenario.read_text(encoding="utf-8")
anchor = """---\n\n## 07. 作戦の目的とゲームの勝利\n"""
insert = """---\n\n### ■ 「次の戦闘」に適用される持ち越し効果\n\n本シナリオで「次の戦闘」「次に発生する戦闘」などと記載された効果は、実際に戦闘が開始するまで保持する。途中で非戦闘イベントが発生しても消費しない。\n\n- 攻撃ロール、防御ロール、敵の攻撃回数、参加人数制限など、種類の異なる持ち越し効果は同じ戦闘に同時に適用する。\n- 同じ種類の数値補正を複数保持している場合、特記がない限りすべて加算する。プラス修正とマイナス修正を同時に保持している場合も合算する。\n- 先制権に関する持ち越し効果だけは1つのみ保持する。「分隊が先制攻撃を行う」または「敵が先制攻撃を行う」を新たに得た場合、それ以前に保持していた先制権の指定を上書きする。\n- 出目52【怒号の群衆】の「分隊側が必ず先制攻撃を行う」など、発生した戦闘そのものに先制権が明記されている場合は、その戦闘固有の記載を最優先する。\n- 「次の戦闘」に対する持ち越し効果は、戦闘が開始した時点で消費する。戦闘固有ルールによって効果が上書き・無効化された場合も、さらに次の戦闘へは持ち越さない。\n\nこの規定は、出目13、22、32、34、36、41～46など、本シナリオ内で「次の戦闘」へ影響を持ち越す効果に適用する。\n\n---\n\n## 07. 作戦の目的とゲームの勝利\n"""
if anchor not in s:
    raise SystemExit("section 07 anchor not found")
if "### ■ 「次の戦闘」に適用される持ち越し効果" not in s:
    s = s.replace(anchor, insert, 1)
scenario.write_text(s, encoding="utf-8")

audit = Path("docs/SCENARIO_V1_01_RESOURCE_BALANCE_AUDIT.md")
a = audit.read_text(encoding="utf-8")
heading = "## 43. Black Sun 『次の戦闘』持ち越し効果の共通処理 — 採用済み"
section = """

## 43. Black Sun 『次の戦闘』持ち越し効果の共通処理 — 採用済み

ユーザー承認により、Black Sun内で「次の戦闘」「次に発生する戦闘」へ持ち越される効果の共通処理を定義する。

- 持ち越し効果は実際に戦闘が開始するまで保持し、途中の非戦闘イベントでは消費しない。
- 攻撃・防御・敵攻撃回数・参加人数制限など種類の異なる効果は同じ戦闘に同時適用する。
- 同じ種類の数値補正も、特記がない限り加算する。プラスとマイナスが同時にある場合は合算する。
- 先制権だけは1つのみ保持し、新たに得た「分隊先制」または「敵先制」が、それ以前の持ち越し先制権を上書きする。
- 出目52【怒号の群衆】の「必ず分隊側が先制」など、戦闘そのものに先制権が明記されている場合は、戦闘固有の指定を最優先する。
- 次の戦闘用の持ち越し効果は戦闘開始時に消費する。戦闘固有ルールによって上書き・無効化された効果も、さらに次の戦闘へ繰り越さない。

これにより、出目13／32の分隊先制と出目45の敵先制が競合した場合は、後から得た情報・警戒状態が優先される。数値系の持ち越し効果は同時に処理でき、戦闘固有ルールは持ち越し状態より優先する。
"""
if heading not in a:
    a = a.rstrip() + section + "\n"
audit.write_text(a, encoding="utf-8")
